        cands.sort(key=lambda t: (-t[0], -t[1]))
        res = []
        best = -1
        for m, c in cands:
            if c > best:
                res.append((m, c))
                best = c
        res.reverse()
        return res

    size = 4 * n + 4
    C0 = [0] * size
    LN = [None] * size

    def set_leaf(node, i):
        a = Aa[i]; b = Bb[i]
        C0[node] = a
        cands = [(1, a)]
        if b + 0 <= INF:
            cands.append((b, 0))
        LN[node] = prune(cands)

    def pull(node):
        L = 2 * node
        R = 2 * node + 1
        cands = []
        LL = LN[L]
        RL = LN[R]
        for mL, cL in LL:
            for mR, cR in RL:
                m = mL * mR
                if m > INF:
                    continue
                c = cL * mR + cR
                if m + c <= INF:
                    cands.append((m, c))
        LN[node] = prune(cands)
        v = C0[L]
        if v == 0:
            C0[node] = C0[R]
        else:
            best = 0
            for mR, cR in RL:
                val = mR * v + cR
                if val > best:
                    best = val
            if best > INF + 1:
                best = INF + 1
            C0[node] = best

    def build(node, lo, hi):
        if lo == hi:
            set_leaf(node, lo)
            return
        mid = (lo + hi) // 2
        build(2 * node, lo, mid)
        build(2 * node + 1, mid + 1, hi)
        pull(node)

    def update(node, lo, hi, p):
        if lo == hi:
            set_leaf(node, lo)
            return
        mid = (lo + hi) // 2
        if p <= mid:
            update(2 * node, lo, mid, p)
        else:
            update(2 * node + 1, mid + 1, hi, p)
        pull(node)

