        filt = [(p, c) for p, c in lines if c <= LIM]
        if not filt:
            # all exceed LIM; keep one (never used for valid answers)
            filt = [min(lines, key=lambda x: x[1])]
        filt.sort()
        ded = []
        for p, c in filt:
            if ded and ded[-1][0] == p:
                ded[-1] = (p, c)
            else:
                ded.append((p, c))
