        for p, c in ded:
            while len(st) >= 2:
                p1, c1 = st[-2]
                p2, c2 = st[-1]
                if (c1 - c) * (p2 - p1) <= (c1 - c2) * (p - p1):
                    st.pop()
                else:
                    break
            st.append((p, c))
        return st

    def merge(L, R):
        cand = []
        for pp, cp in L:
            for pq, cq in R:
                c = pq * cp + cq
                cand.append((pq * pp, c))
        return build(cand)

    def evaluate(h, v):
        lo, hi = 0, len(h) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            p1, c1 = h[mid]
            p2, c2 = h[mid + 1]
            if p2 * v + c2 >= p1 * v + c1:
                lo = mid + 1
            else:
                hi = mid
        p, c = h[lo]
        return p * v + c

    sz = 1
    while sz < n:
        sz <<= 1
    t = [None] * (2 * sz)
    for i in range(sz):
        if i < n:
            t[sz + i] = build([(1, A[i]), (B[i], 0)])
        else:
            t[sz + i] = [(1, 0)]
    for i in range(sz - 1, 0, -1):
        t[i] = merge(t[2 * i], t[2 * i + 1])

    def update_leaf(i):
        j = sz + i
        t[j] = build([(1, A[i]), (B[i], 0)])
        j >>= 1
        while j >= 1:
