            P[i:] += delta
        elif t == b'2':
            i = int(data[ptr+1]); x = int(data[ptr+2]); ptr += 3
            old = B[i]
            if old >= 2:
                idx = bisect.bisect_left(sp, i)
                del sp[idx]
            B[i] = x
            if x >= 2:
                bisect.insort(sp, i)
        else:
            l = int(data[ptr+1]); r = int(data[ptr+2]); ptr += 3
            v = 0
            cur = l
            idx = bisect.bisect_left(sp, l)
            L = len(sp)
            while idx < L and sp[idx] <= r:
                p = sp[idx]
                # gap of pure additions [cur, p-1]
